'use strict';

const state = {
  page: 'home', q: '', heroes: [], items: [], patches: [], guides: [], stats: {},
  selectedHero: null, selectedGuide: null, itemCategory: 'Все', attribute: 'Все', role: 'Все', attackType: 'Все', selectedPatch: null,
  compareLeft: '', compareRight: ''
};
const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const escapeHtml = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const splitTags = value => String(value || '').split(';').map(x => x.trim()).filter(Boolean);
const number = value => Number(value || 0).toLocaleString('ru-RU');
const formatDate = value => { const date = new Date(`${value}T00:00:00`); return Number.isNaN(date.getTime()) ? value : date.toLocaleDateString('ru-RU',{day:'2-digit',month:'short',year:'numeric'}); };
const emblem = name => ({'Axe':'A','Crystal Maiden':'CM','Juggernaut':'J','Lina':'L','Drow Ranger':'DR','Pudge':'P'}[name] || String(name || 'D').slice(0,2).toUpperCase());

async function api(url, options = {}) {
  const response = await fetch(url, { headers: { 'Content-Type':'application/json', ...(options.headers || {}) }, ...options });
  const body = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(body.error || `Ошибка API ${response.status}`);
  return body;
}
const loadPageData = createDataLoader(state, api);
let pageLoad = 0;
let loadingPage = null;
async function showPage(page) {
  const sequence = ++pageLoad;
  loadingPage = page;
  if (page === 'home') renderPage();
  else $('#pageContent').innerHTML = '<div class="content-wrap mx-auto max-w-[1320px] px-[clamp(18px,4vw,56px)] pb-[50px] pt-[35px] max-[760px]:px-[15px] max-[760px]:pt-[27px] max-[760px]:pb-9"><div class="loading-block" role="status">Загружаем раздел…</div></div>';
  try {
    await loadPageData(page);
    if (sequence !== pageLoad) return;
    loadingPage = null;
    $('#apiStatus').textContent = 'Supabase · API OK';
    renderPage();
  } catch (error) {
    if (sequence !== pageLoad) return;
    loadingPage = null;
    $('#apiStatus').textContent = 'API не отвечает';
    $('#pageContent').innerHTML = `<div class="content-wrap mx-auto max-w-[1320px] px-[clamp(18px,4vw,56px)] pb-[50px] pt-[35px] max-[760px]:px-[15px] max-[760px]:pt-[27px] max-[760px]:pb-9"><div class="empty-state col-span-full rounded-[10px] border border-dashed border-[#363b46] px-4 py-10 text-center text-atlas-muted"><h2>Не удалось загрузить раздел</h2><p>${escapeHtml(error.message)}</p><button class="btn-secondary rounded-[9px] border border-atlas-line bg-[#1d212a] px-[14px] py-[9px] text-xs font-semibold text-[#d5d7dc] hover:border-[#535a68]" data-retry-page>Повторить</button></div></div>`;
  }
}
function toast(message) {
  const node = $('#toast'); node.textContent = message; node.classList.add('show');
  clearTimeout(toast.timer); toast.timer = setTimeout(() => node.classList.remove('show'), 2600);
}
function iconText(name) { return ({heroes:'◈',items:'◇',patches:'↟',guides:'▤',compare:'⇄'}[name] || '✦'); }
function heroArt(hero, large = false) {
  const demoImages = {'Axe':'axe','Crystal Maiden':'crystal_maiden','Juggernaut':'juggernaut','Lina':'lina','Drow Ranger':'drow_ranger','Pudge':'pudge'};
  const image = /^https:\/\//i.test(hero.image_url || '') ? hero.image_url : demoImages[hero.name] ? `https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/heroes/${demoImages[hero.name]}.png` : '';
  return `<div class="hero-art${large ? ' large-art' : ''} relative mb-[14px] grid h-[118px] place-items-center overflow-hidden rounded-lg bg-[radial-gradient(circle_at_50%_55%,#46404a_0%,#242631_38%,#191c24_75%)] [&_img]:absolute [&_img]:inset-0 [&_img]:z-[1] [&_img]:h-full [&_img]:w-full [&_img]:object-cover before:absolute before:h-[90px] before:w-[90px] before:rotate-[35deg] before:rounded-full before:border before:border-[#d9a44155] before:content-[''] after:absolute after:h-[90px] after:w-[90px] after:rotate-[35deg] after:rounded-full after:border after:border-[#d9a44155] after:content-[''] after:h-[58px] after:w-[58px] after:rotate-45 after:rounded-xl after:border-[#c23c2a77] [&_small]:absolute [&_small]:left-[10px] [&_small]:top-[9px] [&_small]:z-[2] [&_small]:rounded-[5px] [&_small]:bg-[#14161be8] [&_small]:px-2 [&_small]:py-1 [&_small]:text-xs [&_small]:text-[#f0ce8b] max-[760px]:h-[90px]"><small>${escapeHtml(hero.primary_attribute)}</small><span class="hero-emblem z-[1] grid h-[54px] w-[54px] place-items-center rounded-full border border-[#d9a441aa] bg-[#191b22] text-[25px] font-black text-[#e3ba69] shadow-[0_0_30px_#d9a44110]" aria-hidden="true">${escapeHtml(emblem(hero.name))}</span>${image ? `<img src="${escapeHtml(image)}" alt="" loading="lazy" onerror="this.hidden=true">` : ''}</div>`;
}
function heroCard(hero) {
  return `<a class="hero-card no-underline text-inherit min-w-0 rounded-[11px] border border-[#292e38] bg-atlas-panel p-4 transition hover:-translate-y-0.5 hover:border-[#6b3b35] cursor-pointer [&_h3]:mb-[5px] [&_h3]:mt-0 [&_h3]:text-[15px] [&_h3]:[overflow-wrap:anywhere] max-[760px]:p-[11px] max-[760px]:[&_h3]:text-[13px] max-[420px]:grid max-[420px]:grid-cols-[95px_1fr] max-[420px]:gap-x-3 max-[420px]:[&_.hero-art]:row-span-4 max-[420px]:[&_.hero-art]:h-[94px] max-[420px]:[&_.hero-art]:m-0 max-[420px]:[&_.card-stats]:col-start-2 max-[420px]:[&_.tags]:col-start-2 max-[420px]:[&_.card-actions]:col-span-full max-[420px]:[&_.hero-emblem]:h-10 max-[420px]:[&_.hero-emblem]:w-10 max-[420px]:[&_.hero-emblem]:text-[19px]" href="/heroes/${encodeURIComponent(hero.slug)}" aria-label="Открыть героя ${escapeHtml(hero.name)}">
    ${heroArt(hero)}<h3>${escapeHtml(hero.name)}</h3><p class="subline mb-[10px] mt-0 text-xs text-[#b6bbc6]">${escapeHtml(hero.attack_type)} · ${hero.ability_count || 0} способностей</p>
    <div class="tags flex flex-wrap gap-[5px]">${splitTags(hero.roles).slice(0,3).map(tag => `<span class="tag rounded-[5px] border border-[#303542] bg-[#232732] px-2 py-1 text-xs text-[#d8d9df]">${escapeHtml(tag)}</span>`).join('')}</div>
    <div class="card-stats mt-[14px] flex justify-between gap-2 border-t border-atlas-line pt-[10px] text-xs text-[#b6bbc6]"><span>Здоровье ${number(hero.base_health)}</span><span>Броня ${Number(hero.armor).toFixed(1)}</span></div>
  </a>`;
}
function itemCard(item) {
  const marker = ({'Расходуемые':'✦','Атака':'⚔','Мобильность':'↗','Защита':'⬡','Поддержка':'✚','Улучшение':'✧','Атрибуты':'◇'}[item.category] || '✧');
  const image = Object.hasOwn(ITEM_IMAGES, item.name) ? ITEM_IMAGES[item.name] : '';
  return `<article class="item-card no-underline text-inherit min-w-0 rounded-[11px] border border-[#292e38] bg-atlas-panel p-4 transition hover:-translate-y-0.5 hover:border-[#6b3b35] [&_h3]:mb-[5px] [&_h3]:mt-0 [&_h3]:text-[15px] [&_h3]:[overflow-wrap:anywhere] [&_p]:min-h-12 [&_p]:text-[11px] [&_p]:leading-relaxed [&_p]:text-atlas-muted max-[760px]:p-[11px] max-[760px]:[&_h3]:text-[13px]"><div class="item-art relative mb-3 grid h-24 place-items-center overflow-hidden rounded-lg bg-[linear-gradient(145deg,#29272a,#1b1d24)] text-[25px] font-extrabold text-atlas-gold [&_img]:absolute [&_img]:inset-0 [&_img]:h-full [&_img]:w-full [&_img]:object-contain"><span class="item-art-fallback" aria-hidden="true">${marker}</span>${image ? `<img src="https://cdn.cloudflare.steamstatic.com/apps/dota2/images/dota_react/items/${image}" alt="" loading="lazy" decoding="async" onerror="this.hidden=true">` : ''}</div><div class="tags flex flex-wrap gap-[5px]"><span class="tag rounded-[5px] border border-[#303542] bg-[#232732] px-2 py-1 text-xs text-[#d8d9df]">${escapeHtml(item.category)}</span></div><h3>${escapeHtml(item.name)}</h3><p>${escapeHtml(item.description)}</p><div class="card-stats mt-[14px] flex justify-between gap-2 border-t border-atlas-line pt-[10px] text-xs text-[#b6bbc6]"><span>Стоимость</span><span class="item-cost whitespace-nowrap text-[17px] font-extrabold text-atlas-gold">${number(item.cost)} <small>g</small></span></div><div class="detail-section mt-5 border-t border-[#2c303a] pt-[18px] [&_h3]:mb-[13px] [&_h3]:mt-0 [&_h3]:text-base"><b class="small-label text-[10px] font-extrabold tracking-[1.5px] text-atlas-gold">ЭФФЕКТ</b><p>${escapeHtml(item.effect || item.bonuses || 'Нет описания')}</p></div></article>`;
}
